// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(this));
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            // call succeeded
        } catch {
            // call reverted
        }
        // General rule: no owner was ever set, so owner must remain address(0)
        // regardless of who calls transferOwnership or with what argument.
        assertTrue(c.owner() == address(0));
    }
}

