pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        // hand ownership to the fuzzed actor (initial owner is address(0))
        vm.prank(address(0));
        c.transferOwnership(actor);
        // owner may still move ownership via transferOwnership
        vm.prank(actor);
        c.transferOwnership(actor);
        // calling owned() must NEVER change the owner state
        vm.prank(actor);
        try c.owned() { /* ok */ } catch { /* non-owner path reverts; state untouched */ }
        assertTrue(c.owner() == actor);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address other) public {
        // Keep the domain wide; only exclude the trivial degenerate duplicate.
        vm.assume(actor != other);

        address initialOwner = c.owner();

        // Set the stored owner to the fuzzed actor (owner is address(0) at deploy,
        // so the zero address is the legitimate initial owner/prank source).
        vm.prank(initialOwner);
        c.transferOwnership(actor);
        assert(keccak256(abi.encode(c.owner())) == keccak256(abi.encode(actor)));

        // Drive the entry under test: the (new) owner calls owned().
        vm.prank(actor);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }

        // GENERAL RULE: owned() is a no-op — for every admissible caller it either
        // reverts or leaves the publicly readable owner unchanged. The reference C
        // satisfies this for all inputs; a mutant that writes msg.sender into owner
        // inside owned() violates it (owner would be rewritten by the call).
        assertTrue(ok && c.owner() == actor && keccak256(abi.encode(c.owner())) != keccak256(abi.encode(other)),
            "owned() must not alter the owner state for any caller");
    }
}

